async def _save_config(table_name: str, client_id: str, model: BaseModel, config_data: BaseModel, local_db_pool: AsyncpgPool):
    logger.info(
        f"Attempting to save/update configuration to table: '{table_name}'."
    )
    # local_db_pool: AsyncpgPool = request.app.state.local_db_pool
    # configurations_table_name = "configurations"  # Hardcoded table name for UI configurations
    # io_config_table_name = "io_config"
    # json_config = config_data.model_dump()

    if LOADED_RAW_SCHEMA is None or table_name not in LOADED_RAW_SCHEMA.tables:
        logger.critical(
            f"Configurations table '{table_name}' not defined in schema.yml. Cannot save config."
        )
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail=ApiResponse(
                success=False,
                message=f"Internal server error: '{table_name}' table schema not found. Ensure schema.yml is updated.",
            ).model_dump(),
        )

    # SQL for upsert: INSERT if not exists, UPDATE if exists
    # Requires client_id to be a UNIQUE constraint in the table schema
    upsert_sql = f"""
        INSERT INTO {table_name} (client_id, config_data, last_updated)
        VALUES ($1, $2, $3)
        ON CONFLICT (client_id) DO UPDATE
        SET config_data = EXCLUDED.config_data,
            last_updated = EXCLUDED.last_updated;
    """

    try:
        # current_time = datetime.utcnow()
        current_time = datetime.now(timezone.utc)
        validated_data = model.model_validate(config_data)
        # NEW: Serialize the config_payload.config_json (which is a dict) to a JSON string
        # json_data_to_store = json.dumps(config_data)
        # json_data_to_store = config_data.model_dump()
        json_data_to_store = json.dumps(validated_data.model_dump_json())
        await local_db_pool.execute(
            upsert_sql, client_id, json_data_to_store, current_time
        )  # Pass serialized string

        logger.info(
            f"Successfully saved/updated configuration for client '{client_id}' in table {table_name}."
        )
        return ApiResponse(
            success=True,
            message=f"Configuration for client '{client_id}' saved successfully.",
            data={
                "client_id": client_id,
                "config_data_saved": config_data,
                "last_updated": current_time.isoformat().replace("+00:00", "Z"),
            },
        )
    except ValidationError as e:
        logger.error(
            f"Validation error saving config for client '{client_id}' in table {table_name}: {e.errors()}",
            exc_info=True,
        )
        raise HTTPException(
            status_code=status.HTTP_422_UNPROCESSABLE_ENTITY,
            detail=ApiResponse(
                success=False,
                message="Invalid configuration data provided.",
                data={"errors": e.errors()},
            ).model_dump(),
        )
    except Exception as e:
        # NEW: Convert config_payload.config_json to string for logging to avoid f-string error
        logger.error(
            f"Unexpected error saving configuration for client '{client_id}' in table {table_name} with payload {str(config_data)}: {e}",
            exc_info=True,
        )
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail=ApiResponse(
                success=False, message=f"An unexpected error occurred: {e}"
            ).model_dump(),
        )

